package com.taxplatform.startup;

import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.Executors;

/** Published RFC vectors plus account lifecycle invariants. No conformance certification. */
public final class AccountSecurityTests {
    private static int passed,vectors;
    private static final String PASSWORD="Synthetic-security-password-19";
    private AccountSecurityTests(){ }
    static final class TestClock extends Clock {
        Instant instant=Instant.parse("2026-11-03T05:00:00Z");
        @Override public ZoneId getZone(){return ZoneOffset.UTC;}
        @Override public Clock withZone(ZoneId zone){return this;}
        @Override public Instant instant(){return instant;}
        void advance(long seconds){instant=instant.plusSeconds(seconds);}
    }
    static Map<String,Object> map(Object... entries){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<entries.length;i+=2)m.put((String)entries[i],entries[i+1]);return m;}
    static void eq(Object a,Object b){if(!Objects.equals(a,b))throw new AssertionError(a+" != "+b);}
    static void check(String name,Runnable task){task.run();passed++;System.out.println("PASS "+name);}
    static void fail(String code,Runnable task){try{task.run();throw new AssertionError("accepted "+code);}catch(Workspace.Problem e){eq(e.code,code);}}
    static Map<String,Object> command(AccountSecurity security,String actor,String operation){return map("operation",operation,"expected_security_revision",security.view(actor).get("security_revision"),"password",PASSWORD,"factor_method","","factor_code","");}
    static String otp(String secret,Clock clock){return Totp.at(secret,clock.instant().getEpochSecond()/30,6);}
    static AccountSecurity.Change confirm(AccountSecurity security,String actor,Map<String,Object> setup,Clock clock){Map<String,Object> b=command(security,actor,"CONFIRM_ENROLLMENT");b.put("setup_id",setup.get("setup_id"));b.put("factor_method","TOTP");b.put("factor_code",otp((String)setup.get("secret"),clock));return security.command(actor,b,false);}
    static Map<String,Object> recoveryCommand(AccountSecurity security,String actor,String operation,String code){var b=command(security,actor,operation);b.put("factor_method","RECOVERY_CODE");b.put("factor_code",code);return b;}
    public static void main(String[] args)throws Exception{
        check("RFC6238 published SHA1 eight-digit and six-digit vectors",()->{String key="GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ";long[] times={59,1111111109L,1111111111L,1234567890L,2000000000L,20000000000L};String[] values={"94287082","07081804","14050471","89005924","69279037","65353130"};for(int i=0;i<times.length;i++){eq(Totp.at(key,times[i]/30,8),values[i]);eq(Totp.at(key,times[i]/30,6),values[i].substring(2));vectors+=2;}});
        check("TOTP window rejects malformed expired future and consumed values",()->{String key="GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ";Instant now=Instant.ofEpochSecond(1111111111L);long step=now.getEpochSecond()/30;eq(Totp.verify(key,Totp.at(key,step,6),now,-1),step);eq(Totp.verify(key,Totp.at(key,step,6),now,step),-1L);for(long offset:List.of(-2L,2L))eq(Totp.verify(key,Totp.at(key,step+offset,6),now,-1),-1L);for(String value:List.of("","12345","1234567","１２３４５６","12 456"))eq(Totp.verify(key,value,now,-1),-1L);});
        Path directory=Files.createTempDirectory("security-unit-");TestClock clock=new TestClock();
        try(VaultStore store=new VaultStore(directory.resolve("data"),directory.resolve("key"))){
            Workspace w=new Workspace(store,clock);AccountSecurity security=new AccountSecurity(store,w,clock);String actor=(String)w.register(map("username","security_owner","display_name","Synthetic owner","password",PASSWORD)).get("id"),admin=(String)w.createOperator("security_admin","Synthetic admin",PASSWORD,"ADMIN").get("id");
            Map<String,Object> login=map("username","security_owner","password",PASSWORD);List<Map<String,Object>> setupBox=new ArrayList<>();List<String> codes=new ArrayList<>();
            check("legacy users remain password authenticated without secret defaults",()->{eq(w.passwordLogin(login).mfaRequired(),false);eq(security.view(actor).get("mfa_enabled"),false);eq(security.view(actor).get("security_revision"),0L);});
            check("pending setup does not enable MFA or reveal key in read projection",()->{var setup=security.command(actor,command(security,actor,"START_ENROLLMENT"),false).response();setupBox.add(setup);eq(((String)setup.get("secret")).length(),32);eq(w.passwordLogin(login).mfaRequired(),false);eq(security.view(actor).containsKey("secret"),false);eq(security.view(actor).containsKey("setup_id"),false);eq(security.view(actor).get("pending_enrollment"),true);});
            check("wrong and stale enrollment proofs cannot replace an authenticator",()->{var b=command(security,actor,"CONFIRM_ENROLLMENT");b.put("setup_id",setupBox.get(0).get("setup_id"));b.put("factor_method","TOTP");b.put("factor_code","not-a-code");fail("AUTHENTICATION_PROOF_FAILED",()->security.command(actor,b,false));b.put("setup_id","old-setup");fail("ENROLLMENT_EXPIRED_OR_REPLACED",()->security.command(actor,b,false));eq(security.view(actor).get("mfa_enabled"),false);});
            check("confirmation issues random recovery codes once and revokes old epochs",()->{var change=confirm(security,actor,setupBox.get(0),clock);codes.addAll(Json.list(change.response().get("recovery_codes")).stream().map(String.class::cast).toList());eq(codes.size(),10);eq(codes.stream().distinct().count(),10L);eq(change.epoch(),1L);eq(change.response().containsKey("secret"),false);eq(security.view(actor).get("mfa_enabled"),true);eq(w.passwordLogin(login).mfaRequired(),true);fail("MFA_REQUIRED",()->w.login(login));});
            String secret=(String)setupBox.get(0).get("secret");
            check("enrollment code already consumed and a fresh code authenticates once",()->{fail("AUTHENTICATION_PROOF_FAILED",()->security.finishLogin(actor,1,map("method","TOTP","code",otp(secret,clock))));clock.advance(30);var proof=security.finishLogin(actor,1,map("method","TOTP","code",otp(secret,clock)));eq(proof.userId(),actor);fail("AUTHENTICATION_PROOF_FAILED",()->security.finishLogin(actor,1,map("method","TOTP","code",otp(secret,clock))));});
            check("recovery codes are single use and do not disable MFA",()->{security.finishLogin(actor,1,map("method","RECOVERY_CODE","code",codes.get(0)));eq(security.view(actor).get("recovery_codes_remaining"),9);fail("AUTHENTICATION_PROOF_FAILED",()->security.finishLogin(actor,1,map("method","RECOVERY_CODE","code",codes.get(0))));eq(security.view(actor).get("mfa_enabled"),true);});
            check("security read case export audit and encrypted disk never disclose codes",()->{String id=(String)w.createCase(actor,map("title","Security export fixture","request_id",Workspace.id())).get("id"),visible=Json.encode(security.view(actor))+Json.encode(w.exportCase(actor,id))+Json.encode(w.audit(admin))+Json.encode(w.account(actor));for(String code:codes)eq(visible.contains(code),false);eq(visible.contains(secret),false);String rows=store.read(state->Json.encode(state));for(String code:codes)eq(rows.contains(code),false);eq(rows.contains("last_totp_step"),true);try{String disk=new String(Files.readAllBytes(directory.resolve("data/workspace.vault")),java.nio.charset.StandardCharsets.ISO_8859_1);eq(disk.contains(secret),false);for(String code:codes)eq(disk.contains(code),false);}catch(java.io.IOException e){throw new AssertionError(e);}});
            check("current password is required before consuming a recovery proof",()->{var b=recoveryCommand(security,actor,"REVOKE_OTHER_SESSIONS",codes.get(1));b.put("password","Wrong-current-password");fail("AUTHENTICATION_PROOF_FAILED",()->security.command(actor,b,false));eq(security.view(actor).get("recovery_codes_remaining"),9);});
            check("stale settings and field injection cannot consume a valid recovery code",()->{var b=recoveryCommand(security,actor,"REVOKE_OTHER_SESSIONS",codes.get(1));b.put("expected_security_revision",0L);fail("STALE_SECURITY_SETTINGS",()->security.command(actor,b,false));b.put("expected_security_revision",security.view(actor).get("security_revision"));b.put("mfa_enabled",false);fail("UNEXPECTED_FIELDS",()->security.command(actor,b,false));eq(security.view(actor).get("recovery_codes_remaining"),9);});
            check("revocation rejects old request context inside reads and transactions",()->{String id=(String)w.createCase(actor,map("title","Epoch fixture","request_id",Workspace.id())).get("id");var edit=map("operation","RENAME","request_id",Workspace.id(),"expected_revision",w.readCase(actor,id).get("revision"),"title","New title");w.bindSession(actor,1);try{var change=security.command(actor,recoveryCommand(security,actor,"REVOKE_OTHER_SESSIONS",codes.get(1)),false);eq(change.epoch(),2L);fail("SESSION_ENDED",()->w.readCase(actor,id));fail("SESSION_ENDED",()->w.edit(actor,id,edit));}finally{w.clearSession();}eq(w.readCase(actor,id).get("title"),"Epoch fixture");fail("MFA_CHALLENGE_EXPIRED",()->security.finishLogin(actor,1,map("method","RECOVERY_CODE","code",codes.get(2))));});
            check("regenerating recovery codes invalidates the complete previous set",()->{var change=security.command(actor,recoveryCommand(security,actor,"REGENERATE_CODES",codes.get(2)),false);eq(change.epoch(),3L);List<String> old=new ArrayList<>(codes);codes.clear();codes.addAll(Json.list(change.response().get("recovery_codes")).stream().map(String.class::cast).toList());fail("AUTHENTICATION_PROOF_FAILED",()->security.finishLogin(actor,3,map("method","RECOVERY_CODE","code",old.get(3))));eq(security.view(actor).get("recovery_codes_remaining"),10);});
            check("replacement leaves original MFA active until fresh setup confirmed",()->{var setup=security.command(actor,recoveryCommand(security,actor,"START_ENROLLMENT",codes.get(0)),false).response();eq(w.passwordLogin(login).mfaRequired(),true);eq(w.authenticationEpoch(actor),3L);clock.advance(30);security.finishLogin(actor,3,map("method","TOTP","code",otp(secret,clock)));var replacement=confirm(security,actor,setup,clock);eq(replacement.epoch(),4L);codes.clear();codes.addAll(Json.list(replacement.response().get("recovery_codes")).stream().map(String.class::cast).toList());});
            check("expired setup cannot activate and cancel keeps active factor",()->{var setup=security.command(actor,recoveryCommand(security,actor,"START_ENROLLMENT",codes.get(0)),false).response();clock.advance(600);fail("ENROLLMENT_EXPIRED_OR_REPLACED",()->confirm(security,actor,setup,clock));security.command(actor,recoveryCommand(security,actor,"CANCEL_ENROLLMENT",codes.get(1)),false);eq(security.view(actor).get("mfa_enabled"),true);eq(security.view(actor).get("pending_enrollment"),false);});
            check("HTTPS operator policy prevents disabling before consuming a proof",()->{int before=(int)security.view(actor).get("recovery_codes_remaining");fail("OPERATOR_MFA_REQUIRED",()->security.command(actor,recoveryCommand(security,actor,"DISABLE_MFA",codes.get(2)),true));eq(security.view(actor).get("recovery_codes_remaining"),before);});
            check("password change verifies old credentials and invalidates outstanding epoch",()->{var b=recoveryCommand(security,actor,"CHANGE_PASSWORD",codes.get(2));b.put("new_password","Synthetic-new-password-20");var result=security.command(actor,b,false);eq(result.epoch(),5L);fail("LOGIN_FAILED",()->w.passwordLogin(login));eq(w.passwordLogin(map("username","security_owner","password","Synthetic-new-password-20")).mfaRequired(),true);});
            check("factor failures persist and throttle the account across service objects",()->{for(int i=0;i<6;i++){final String code=i==5?"AUTHENTICATION_RATE_LIMIT":"AUTHENTICATION_PROOF_FAILED";fail(code,()->new AccountSecurity(store,w,clock).finishLogin(actor,5,map("method","RECOVERY_CODE","code","invalid")));}fail("AUTHENTICATION_RATE_LIMIT",()->security.finishLogin(actor,5,map("method","RECOVERY_CODE","code",codes.get(3))));clock.advance(600);security.finishLogin(actor,5,map("method","RECOVERY_CODE","code",codes.get(3)));eq(security.view(actor).get("factor_locked_until"),"");});
            check("parallel reuse of one recovery code succeeds at most once",()->{var pool=Executors.newFixedThreadPool(4);try{List<java.util.concurrent.Future<Boolean>> jobs=new ArrayList<>();for(int i=0;i<4;i++)jobs.add(pool.submit(()->{try{security.finishLogin(actor,5,map("method","RECOVERY_CODE","code",codes.get(4)));return true;}catch(Workspace.Problem e){eq(e.code,"AUTHENTICATION_PROOF_FAILED");return false;}}));int count=0;for(var job:jobs)try{if(job.get())count++;}catch(Exception e){throw new AssertionError(e);}eq(count,1);}finally{pool.shutdownNow();}});
            check("MFA removal requires password and unused factor; future login is explicit",()->{var b=recoveryCommand(security,actor,"DISABLE_MFA",codes.get(5));b.put("password","Synthetic-new-password-20");var result=security.command(actor,b,false);eq(result.epoch(),6L);eq(security.view(actor).get("mfa_enabled"),false);eq(security.view(actor).get("recovery_codes_remaining"),0);eq(w.passwordLogin(map("username","security_owner","password","Synthetic-new-password-20")).mfaRequired(),false);});
        }finally{try(var paths=Files.walk(directory)){for(Path p:paths.sorted(java.util.Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}}
        System.out.println(Json.encode(Map.of("security_named_groups",passed,"published_rfc_vectors",vectors,"conformance_certification",false,"tax_approval",false)));
    }
}
